INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1374614, 174749, 36956, '<td valign="top">Omg, five zoomdaks, now my chances of ever winning any ribbon are thwarted... lol, genious idea!</td>', 'Omg, five zoomdaks, now my chances of ever winning any ribbon are thwarted... lol, genious idea!', '2005-05-10 02:25:11.000000', NULL, 1),
(1374615, 174608, 36299, '<td valign="top">I always love piano shots, not that I can play one.  A few things, it seems a tad to soft and there is noticeable distortion in the whites and the black piano keys do not stand out.  Possibly less light and a longer exposure would clear this up.  The cropping of this is perfect, difference in tone between black keys and white is good. 7</td>', 'I always love piano shots, not that I can play one.  A few things, it seems a tad to soft and there is noticeable distortion in the whites and the black piano keys do not stand out.  Possibly less light and a longer exposure would clear this up.  The cropping of this is perfect, difference in tone between black keys and white is good. 7', '2005-05-10 02:25:24.000000', NULL, 1),
(1374622, 174689, 36299, '<td valign="top">I like this photo.  The fruit stand out nicely.  The white background overpowers this image for me, a Chinese red or oriental setting would make this outstanding to me.  Some of the white flecks are distracting, even if they do belong there. 7</td>', 'I like this photo.  The fruit stand out nicely.  The white background overpowers this image for me, a Chinese red or oriental setting would make this outstanding to me.  Some of the white flecks are distracting, even if they do belong there. 7', '2005-05-10 02:31:20.000000', NULL, 1),
(1374623, 174555, 36299, '<td valign="top">This is a very nice photo.  I like the contrast between the cans. There is some jaggedness in the curves of the cans which work against this photo. 9</td>', 'This is a very nice photo.  I like the contrast between the cans. There is some jaggedness in the curves of the cans which work against this photo. 9', '2005-05-10 02:33:32.000000', NULL, 1),
(1374624, 174339, 36299, '<td valign="top">I love the shallow DOF here.  If the glare on the edges could of been subdued a little it would of been perfect to me. 9</td>', 'I love the shallow DOF here.  If the glare on the edges could of been subdued a little it would of been perfect to me. 9', '2005-05-10 02:35:08.000000', NULL, 1),
(1374627, 174306, 36299, '<td valign="top">I like the reflection of Mayonnaise in the mirrors.  Cool idea.  It would be nicer if the reflection was more in focus, and a little better spacing in the reflections. 8</td>', 'I like the reflection of Mayonnaise in the mirrors.  Cool idea.  It would be nicer if the reflection was more in focus, and a little better spacing in the reflections. 8', '2005-05-10 02:41:01.000000', NULL, 1),
