(1374664, 174312, 31742, '<td valign="top">Great work ....10</td>', 'Great work ....10', '2005-05-10 03:18:15.000000', NULL, 1),
(1374715, 174523, 35513, '<td valign="top">I REALLY like this photo!  It''s one of my top favorites for this challenge.  The lighting is great and I love the composition.  The colors look incredible.  Just a great shot all around.</td>', 'I REALLY like this photo!  It''s one of my top favorites for this challenge.  The lighting is great and I love the composition.  The colors look incredible.  Just a great shot all around.', '2005-05-10 03:57:59.000000', NULL, 1),
(1374718, 174812, 35513, '<td valign="top">This shot really jumped out at me as one of my favorites.  I like that you chose to make the fluffy parts the focus of the shot.  They are beautifully clear and really stand out.  Excellent lighting.  LOVE the B&amp;W.  Great shot!!!</td>', 'This shot really jumped out at me as one of my favorites.  I like that you chose to make the fluffy parts the focus of the shot.  They are beautifully clear and really stand out.  Excellent lighting.  LOVE the B&W.  Great shot!!!', '2005-05-10 03:58:50.000000', NULL, 1),
(1374720, 174799, 35513, '<td valign="top">Would never have thought to look for five here!  But I love the shot.  The B&amp;W was a great choice.  Everything looks crystal clear!!!  Very creative, it''s good to see something new.  Well done!</td>', 'Would never have thought to look for five here!  But I love the shot.  The B&W was a great choice.  Everything looks crystal clear!!!  Very creative, it''s good to see something new.  Well done!', '2005-05-10 03:59:41.000000', NULL, 1),
(1374722, 174496, 35513, '<td valign="top">Beautiful shot of one of my favorite plants!!!  Excellent focus and clarity.  The colors really jump out at me.  The foliage in the background looks beautiful.</td>', 'Beautiful shot of one of my favorite plants!!!  Excellent focus and clarity.  The colors really jump out at me.  The foliage in the background looks beautiful.', '2005-05-10 04:00:15.000000', NULL, 1),
(1374723, 174943, 35513, '<td valign="top">Great composition!!!!  The lines are so perfectly perpendicular and parallel!!  Really great job taking your time and seeting this up.  The B&amp;W works really well on this shot.  I think it shows a lot of detail in the wood that might be lost in color.  It also really shows off the window panes that are missing.  Wouldn''t change a thing!</td>', 'Great composition!!!!  The lines are so perfectly perpendicular and parallel!!  Really great job taking your time and seeting this up.  The B&W works really well on this shot.  I think it shows a lot of detail in the wood that might be lost in color.  It also really shows off the window panes that are missing.  Wouldn''t change a thing!', '2005-05-10 04:01:31.000000', NULL, 1),
(1374724, 174830, 35513, '<td valign="top">Good lighting, good composition.  A very excellent shot!!  Great focus and clarity.</td>', 'Good lighting, good composition.  A very excellent shot!!  Great focus and clarity.', '2005-05-10 04:01:59.000000', NULL, 1),
(1374728, 174357, 32742, '<td valign="top">I love this photo.</td>', 'I love this photo.', '2005-05-10 04:10:03.000000', NULL, 1),
