(1381245, 175058, 37529, '<td valign="top">I like the colors on the black bacground.</td>', 'I like the colors on the black bacground.', '2005-05-12 13:33:42.000000', NULL, 1),
(1381250, 174969, 37529, '<td valign="top">Nice composition and very original.</td>', 'Nice composition and very original.', '2005-05-12 13:35:53.000000', NULL, 1),
(1381253, 174339, 37529, '<td valign="top">The narrow DOF makes the coins edges stand out nicely.  Good shot.</td>', 'The narrow DOF makes the coins edges stand out nicely.  Good shot.', '2005-05-12 13:37:14.000000', NULL, 1),
(1381256, 174441, 37529, '<td valign="top">I like this shot.  Good composition too.  The black background really makes the red standout and makes for a good focal point too.</td>', 'I like this shot.  Good composition too.  The black background really makes the red standout and makes for a good focal point too.', '2005-05-12 13:39:25.000000', NULL, 1),
