(1383162, 175000, 26679, '<td valign="top">The idea is simple, however for an image that replicates a traditional product shot, I would like to see a little less reflection on the top third of the jars.</td>', 'The idea is simple, however for an image that replicates a traditional product shot, I would like to see a little less reflection on the top third of the jars.', '2005-05-13 06:06:53.000000', NULL, 1),
(1383165, 174722, 26679, '<td valign="top">this is an excellent idea and the composition is strong. For me the grain in the background  material is a little distracting.</td>', 'this is an excellent idea and the composition is strong. For me the grain in the background  material is a little distracting.', '2005-05-13 06:10:51.000000', NULL, 1),
